var url = java.ajax(source.key).match(/window\.location\.href=\'([^']+)/)[1];
java.log(url);
cookie.removeCookie(url);
var kku = url.replace(/m\/.*html$/,"m");
java.log(kku);
var ckk = String(java.get(url,{}).body());
//java.log(ckk)
if (ckk.match(/Checking your browser before accessing/)) {
   java.webView(null, url, "document.cookie")
   cok = cookie.getCookie(url)
   head = JSON.stringify({ headers: { 'Cookie': cok } })
   u = url + "," + head
   java.ajax(u)
}
k=java.createSymmetricCrypto("AES/CBC/PKCS7Padding", "zc89s30ipHG2Dw\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00", "zc89s30ipHG2Dw\x00\x00").encryptBase64(key)
var result = kku + "/k-" + k + "-{{page}}.html"
result;

